{
  "id": "c23",
  "subject": "feat(hybrid): V-scratch page above program RAM (L26) + VLEN 128..1024 (L11)",
  "body_points": [
    "the V transport scratch is the mmap's top page at ram_base + --mem-size, where no program layout can collide; the driver maps one extra page and rejects ELFs whose static image reaches into it",
    "a producer whose vlenb exceeds HYBRID_VLEN_BYTES_MAX refuses to drain instead of truncating; VLEN 128..1024 proven"
  ],
  "construct": "shm.cpp v_scratch page (if deferred from c14), cmd_run ELF-fit rejection, plugin vlenb guard + v_drain_policy hook, break_vscratch{,_top}.S + rt_c_v_fill.c + Makefile + run_e2e entries, tests/hybrid/e2e_vlen1024_drain.sh.",
  "validate": [
    "make -C qemu_plugin && make -C tests/fixtures",
    "driver unit tests"
  ]
}

