// break_vscratch.S
//
// Bug: kVScratchGpa (0x00FF0000) is unconditionally overwritten by the V
// register transport during ResumeDriver::resume() on every V-capable core,
// even for programs that never execute a V instruction.  User data placed at
// that address is silently corrupted before the ROI runs its first instruction.
//
// The linker script marks 0x00FF0000 as V_SCRATCH in its comment, but there is
// no hardware guard and no documented trap for programs that access it directly.
//
// Expected outcome (V-capable core, e.g. ax45mpv_premium):
//   - ResumeDriver::pb_v_data_sweep loads v0..v31 FROM 0x00FF0000 into the
//     vector regfile.  stage_v_to_scratch wrote vreg[] (QEMU1-drained bytes,
//     usually zeros for a program that never used V) into that region first.
//   - The sentinel 0xDEADBEEFCAFEBABE is gone; in-ROI check fires -> hang.
//   - Harness timeout -> FAIL.
//
// Expected outcome (non-V core or HYBRID_FLAG_V not set): PASS (no transport).
//
// Scope: bare-metal, no async interrupts.

.section .text
.globl _start
_start:
    // Write a known sentinel to kVScratchGpa before the ROI.
    li   t0, 0x00FF0000
    li   t1, 0xDEADBEEFCAFEBABE
    sd   t1, 0(t0)              // sentinel lives at scratch GPA

    // t0 and t1 survive the GPR restore because they are drained here by
    // QEMU1 and restored after the V sweep (ResumeDriver restores GPRs last).
    slti x0, x0, 0x5A0          // ENTER ROI

    // After resume: V transport wrote v0's register bytes to 0x00FF0000.
    // On a fresh program that never used V, those bytes are zeros (QEMU1
    // drained v0..v31 = zero).
    ld   t2, 0(t0)              // reload from scratch GPA
    bne  t2, t1, regress        // corrupted? -> infinite loop -> harness FAIL

    slti x0, x0, 0x5A1          // EXIT ROI (only reached if V transport absent)

    li   t0, 0xe0080000         // SimControl: exit code 0 for standalone run
    sw   x0, 0(t0)
1:  j    1b

regress:
    j    regress                // V transport clobbered sentinel -> hang
############ break_vscratch_top.S ############
// break_vscratch_top.S
//
// L26 scheme-D guard: proves the V-transport scratch sits ABOVE the program's
// declared RAM, not on its top page.
//
// This fixture stores a sentinel at 0x07FFF000 -- the LAST page of a default
// 128 MiB program RAM (ceiling 0x08000000). It then enters the ROI (handing
// off to vsim, which advertises V and so runs the V-register transport even
// though this program never executes a V instruction) and reads the sentinel
// back inside the ROI.
//
//   - Scheme A (F1: scratch = top page of the program's RAM): the transport
//     would write v0..v31 to 0x07FFF000 and clobber the sentinel -> the in-ROI
//     check fails, the fixture spins, the harness times out (FAIL).
//   - Scheme D (F2: mmap is one page larger than --mem-size, scratch at the
//     ceiling 0x08000000): 0x07FFF000 is untouched -> sentinel survives ->
//     fixture reaches the exit marker and exits cleanly (PASS).
//
// Must be run with the default 128 MiB program RAM (the 0x07FFF000 literal
// assumes ceiling 0x08000000) on a V-capable engine, e.g.
//   andesim run --mode hybrid --engine vsim:ax45mpv_premium
//       --trigger marker tests/fixtures/break_vscratch_top.elf
//
// Scope: bare-metal, no async interrupts.

.section .text
.globl _start
_start:
    li      t0, 0x07FFF000          // last page of the 128 MiB program RAM
    li      t1, 0xA5A5F00DCAFEBABE
    sd      t1, 0(t0)               // sentinel in the program's top page

    slti    x0, x0, 0x5A0           // ENTER ROI -> hand off to vsim

    ld      t2, 0(t0)               // reload after the V transport ran
    bne     t2, t1, regress         // clobbered (scheme A)? spin -> harness FAIL

    slti    x0, x0, 0x5A1           // EXIT ROI (scheme D: sentinel survived)

    li      t0, 0xe0080000          // SimControl exit for the standalone path
    sw      x0, 0(t0)
1:  j       1b

regress:
    j       regress                 // scratch landed on the top page -> hang
############ rt_c_v_fill.c ############
/* rt_c_v_fill.c - Round-trip fixture: a fully filled V register across the
 * handoff (L11).
 *
 * Unlike rt_c_v_regs (e32 kernel, vl set from the data count), this fixture
 * fills v8 across ALL vlenb bytes (vsetvli AVL=VLMAX, e8/m1), so the drained
 * vreg slot is deterministic end to end at any VLEN. The old wire format
 * clamped the drain at 64 bytes per register; tests/hybrid/
 * e2e_vlen1024_drain.sh runs the QEMU leg at vlen=1024 and asserts the LAST
 * byte of v8 (vreg offset 1023 .. 1151 in the file) survives un-truncated.
 *
 * Phase 1 (QEMU1): v8 = 0xA5 repeated vlenb times, then the enter marker.
 * Phase 2 (vsim): the in-ROI self-check stores v8 and compares every byte;
 *   on mismatch it exits 1, so the vsim leg returns 1 instead of 200 and
 *   the harness fails loudly. On success v8 is refilled with the sentinel
 *   0x5A for StateDrain to capture at the exit marker.
 *
 * crt0.S sets mstatus.VS=Initial, so V is usable in M-mode on both engines.
 * The insns after the exit marker touch no V state, so the drain's 0-3 insn
 * halt slack cannot disturb the sentinel.
 */
#include <stdlib.h>

#include "runtime/rt_c_helpers.h"

#define FILL_BYTE 0xA5u
#define SENTINEL_BYTE 0x5Au

/* HYBRID_VLEN_BYTES_MAX mirror: big enough for VLEN 1024. */
static unsigned char buf[128];

/* vl=VLMAX at e8/m1 covers the whole register; returns vlenb. The "=&r"
 * early-clobber is required: vsetvli writes %0 before vmv.v.x reads %1,
 * so they must not share a register. */
static unsigned long fill_v8(unsigned long pattern)
{
  unsigned long vl;
  asm volatile("vsetvli %0, x0, e8, m1, ta, ma\n\t"
               "vmv.v.x v8, %1"
               : "=&r"(vl)
               : "r"(pattern));
  return vl;
}

static void store_v8(unsigned char *dst)
{
  unsigned long vl;
  asm volatile("vsetvli %0, x0, e8, m1, ta, ma\n\t"
               "vse8.v v8, (%1)"
               : "=&r"(vl)
               : "r"(dst)
               : "memory");
}

int main(void)
{
  /* Phase 1 (QEMU1): fill the full register width. */
  unsigned long vlenb = fill_v8(FILL_BYTE);
  if (vlenb > sizeof(buf))
    exit(2); /* engine wider than the wire format; should have aborted */

  enter_vsim();

  /* Phase 2 (vsim): every restored byte must carry the pattern. */
  store_v8(buf);
  for (unsigned long i = 0; i < vlenb; ++i)
    if (buf[i] != FILL_BYTE)
      exit(1);

  /* Leave a distinct value for the exit drain to capture. */
  fill_v8(SENTINEL_BYTE);

  exit_vsim();

  return 0;
}

