69	  // A "0x"/"0X" address is used verbatim with the prefix stripped (roi.sh
70	  // `${boundary#0[xX]}`); the .symtab is never touched.
71	  if (boundary.starts_with("0x") || boundary.starts_with("0X")) {
72	    std::string addr = boundary.substr(2);
73	    // Must be all hex digits: a verbatim pass of e.g. "ZZZ"/"10zz" would let the
74	    // downstream strtoull silently truncate to 0x0/0x10 (wrong PC window).
75	    if (addr.empty() ||
76	        addr.find_first_not_of("0123456789abcdefABCDEF") != std::string::npos) {
77	      err = "malformed address '" + boundary + "'";
78	      return "";
