87	  // Scan section headers for a symbol table; resolve names through its linked
88	  // string table (sh_link).
89	  for (unsigned i = 0; i < eh.e_shnum; ++i) {
90	    Elf64_Shdr sym_sh;
91	    if (!load(buf, eh.e_shoff + static_cast<size_t>(i) * eh.e_shentsize, sym_sh))
