135	    if (!load(buf, eh.e_shoff + static_cast<size_t>(i) * eh.e_shentsize, sym_sh))
136	      break;
137	    if (sym_sh.sh_type != SHT_SYMTAB || sym_sh.sh_entsize == 0) continue;
138	
139	    Elf64_Shdr str_sh;
140	    if (sym_sh.sh_link >= eh.e_shnum ||
141	        !load(buf, eh.e_shoff + static_cast<size_t>(sym_sh.sh_link) * eh.e_shentsize,
142	              str_sh))
143	      continue;
144	
145	    const size_t nsym = sym_sh.sh_size / sym_sh.sh_entsize;
146	    for (size_t s = 0; s < nsym; ++s) {
147	      Elf64_Sym sym;
