149	      if (sym.st_shndx == SHN_UNDEF) continue;
150	      if (ELF64_ST_TYPE(sym.st_info) != STT_FUNC) continue;
151	      if (sym.st_value > addr) continue;
152	      // With a size, require coverage; without, accept as a preceding label.
153	      if (sym.st_size != 0 && addr >= sym.st_value + sym.st_size) continue;
154	      if (found && sym.st_value <= best_value) continue;
155	
156	      const size_t noff = str_sh.sh_offset + sym.st_name;
157	      if (noff >= buf.size()) continue;
158	      const char* name = buf.data() + noff;
159	      const size_t avail = buf.size() - noff;
